python3 -c "
import pandas as pd

df = pd.read_csv('/root/ckd_lab_data_harmonized.csv', dtype=str)

# Verify column count matches input
df_orig = pd.read_csv('/root/environment/data/ckd_lab_data.csv', dtype=str)
print(f'Input columns: {len(df_orig.columns)}')
print(f'Output columns: {len(df.columns)}')
print(f'Columns match: {list(df_orig.columns) == list(df.columns)}')
print()

# Check no scientific notation anywhere
import re
sci_pattern = re.compile(r'[eE][+-]?\d')
for col in df.columns:
    for v in df[col]:
        if sci_pattern.search(str(v)):
            print(f'Found scientific notation: {col} = {v}')
            break
else:
    print('No scientific notation in any column')

# Check no commas
for col in df.columns:
    for v in df[col]:
        if ',' in str(v):
            print(f'Found comma: {col} = {v}')
            break
else:
    print('No commas in any column')

# Check format X.XX for numeric columns
import re
for col in df.columns[1:]:
    for v in df[col]:
        if not re.match(r'^-?\d+\.\d{2}$', str(v)):
            print(f'Format issue: {col} = {v}')
            break
else:
    print('All numeric values have X.XX format')

# Check patient_id is integer
print(f'patient_id range: {df[\"patient_id\"].astype(int).min()} - {df[\"patient_id\"].astype(int).max()}')
print(f'Rows: {df.shape[0]}')
"
